const std = @import("std");

pub fn recite(buffer: []u8, start_verse: u32, end_verse: u32) ![]const u8 {
    // Build the output string using std.fmt
    const fmt = std.fmt;
    // Determine required size: we can estimate 4000 is enough.
    const out_buf = try std.heap.page_allocator.alloc(u8, 4096);
    defer std.heap.page_allocator.free(u8, out_buf);

    var writer = try fmt.Formatter.init(&out_buf);
    // Write verses
    for (start_verse..=end_verse) |verse| {
        // ordinal
        const ordinal = switch (verse) {
            1 => "first",
            2 => "second",
            3 => "third",
            4 => "fourth",
            5 => "fifth",
            6 => "sixth",
            7 => "seventh",
            8 => "eighth",
            9 => "ninth",
            10 => "tenth",
            11 => "eleventh",
            12 => "twelfth",
            else => @panic("invalid verse"),
        };
        try writer.print("On the {} day of Christmas my true love gave to me: ", .{ordinal});
        // gifts
        for (verse..=1) |day| {
            const phrase = switch (day) {
                1 => "a Partridge in a Pear Tree",
                2 => "two Turtle Doves",
                3 => "three French Hens",
                4 => "four Calling Birds",
                5 => "five Gold Rings",
                6 => "six Geese-a-Laying",
                7 => "seven Swans-a-Swimming",
                8 => "eight Maids-a-Milking",
                9 => "nine Ladies Dancing",
                10 => "ten Lords-a-Leaping",
                11 => "eleven Pipers Piping",
                12 => "twelve Drummers Drumming",
                else => @panic("invalid day"),
            };
            // handle "and" before last phrase when verse > 1
            if (verse > 1 and day == 1) {
